display.text:
type Status = "open" | "done";

type Task = {
  id: number;
  title: string;
  status: Status;
  createdAt: string;
  completedAt?: string;
  tags: string[];
  due?: string;
};

type Database = { tasks: Task[]; nextId: number };

const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  console.error(message);
  process.exit(1);
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function today(): string {
  const date = new Date();
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}

async function loadDatabase(): Promise<Database> {
  const file = Bun.file(databasePath);
  if (!(await file.exists())) return { tasks: [], nextId: 1 };

  let parsed: unknown;
  try {
    parsed = JSON.parse(await file.text());
  } catch {
    fail(`Malformed database: ${databasePath}`);
  }

  if (
    !parsed || typeof parsed !== "object" || Array.isArray(parsed) ||
    !Array.isArray((parsed as Database).tasks) ||
    !Number.isInteger((parsed as Database).nextId) || (parsed as Database).nextId < 1
  ) {
    fail(`Malformed database: ${databasePath}`);
  }
  return parsed as Database;
}

async function saveDatabase(database: Database): Promise<void> {
  const directory = databasePath.includes("/") ? databasePath.slice(0, databasePath.lastIndexOf("/")) || "." : ".";
  const temporary = `${directory}/.${databasePath.split("/").pop()}.tmp-${process.pid}-${Date.now()}`;
  try {
    await Bun.write(temporary, `${JSON.stringify(database, null, 2)}\n`);
    await Bun.write(temporary, Bun.file(temporary));
    const result = Bun.spawnSync(["mv", temporary, databasePath]);
    if (result.exitCode !== 0) fail(`Could not save database: ${databasePath}`);
  } catch {
    fail(`Could not save database: ${databasePath}`);
  }
}

function parseOptions(args: string[], allowed: string[]): Record<string, string> {
  const options: Record<string, string> = {};
  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    const value = args[index + 1];
    if (!allowed.includes(flag) || value === undefined || options[flag] !== undefined) fail(`Invalid option: ${flag}`);
    options[flag] = value;
  }
  return options;
}

function parseId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value) || Number(value) < 1) fail("Invalid task id");
  return Number(value);
}

function normalizedTags(value: string | undefined): string[] {
  if (!value) return [];
  return [...new Set(value.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
}

function print(value: unknown): void {
  console.log(JSON.stringify(value));
}

const [command, ...args] = process.argv.slice(2);
const database = await loadDatabase();

if (command === "add") {
  const options = parseOptions(args, ["--title", "--tags", "--due"]);
  const title = options["--title"]?.trim();
  if (!title) fail("Title is required");
  if (options["--due"] && !isDate(options["--due"])) fail("Invalid due date");
  const task: Task = { id: database.nextId++, title, status: "open", createdAt: new Date().toISOString(), tags: normalizedTags(options["--tags"]) };
  if (options["--due"]) task.due = options["--due"];
  database.tasks.push(task);
  await saveDatabase(database);
  print(task);
} else if (command === "list") {
  const options = parseOptions(args, ["--status", "--tag", "--overdue"]);
  if (options["--status"] && options["--status"] !== "open" && options["--status"] !== "done") fail("Invalid status");
  if (options["--overdue"] && !isDate(options["--overdue"])) fail("Invalid overdue date");
  const tag = options["--tag"]?.trim().toLowerCase();
  print(database.tasks.filter((task) =>
    (!options["--status"] || task.status === options["--status"]) &&
    (!tag || task.tags.includes(tag)) &&
    (!options["--overdue"] || (task.status === "open" && !!task.due && task.due < options["--overdue"])),
  ).sort((a, b) => a.id - b.id));
} else if (command === "done" || command === "delete") {
  if (args.length !== 1) fail(`Usage: ${command} ID`);
  const task = database.tasks.find((candidate) => candidate.id === parseId(args[0]));
  if (!task) fail("Task not found");
  if (command === "done") {
    if (task.status !== "done") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    print(task);
  } else {
    database.tasks = database.tasks.filter((candidate) => candidate !== task);
    await saveDatabase(database);
    print(task);
  }
} else if (command === "stats") {
  if (args.length) fail("Usage: stats");
  const open = database.tasks.filter((task) => task.status === "open");
  print({ total: database.tasks.length, open: open.length, done: database.tasks.length - open.length, overdue: open.filter((task) => task.due && task.due < today()).length });
} else {
  fail("Unknown command");
}

